window.kbPageData["views/entry/k-2a0c6aa1ae74cc31"] = {"key":"entry/k-2a0c6aa1ae74cc31","state":{"route":"entry/k-2a0c6aa1ae74cc31"},"node":{"id":"k-2a0c6aa1ae74cc31","mode":"k","title":"地位、形成与发展","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["事实与事件"],"出处性质":["理论手册"],"学科":["政治理论"],"来源主题":["新时代中国特色社会主义思想"],"资料类别":["非时政"]},"directorySummary":"习近平新时代中国特色社会主义思想是当代中国马克思主义、二十一世纪马克思主义，\n是中华文化和中国精神的时代精华，实现了马克思主义中国化新的飞跃。习近平同志是习近\n平新时代中国特色社会主义思想的主要创立者。\n党的十九大把习近平新时代中国特色社会主义思想确立为我们党必须长期坚持的指导\n思想，并在党章中把习…","sources":[{"id":"96042e2e2eb458e7","label":"地位、形成与发展","topic":"新时代中国特色社会主义思想","category":"非时政","text":"习近平新时代中国特色社会主义思想是当代中国马克思主义、二十一世纪马克思主义，\n是中华文化和中国精神的时代精华，实现了马克思主义中国化新的飞跃。习近平同志是习近\n平新时代中国特色社会主义思想的主要创立者。\n党的十九大把习近平新时代中国特色社会主义思想确立为我们党必须长期坚持的指导\n思想，并在党章中把习近平新时代中国特色社会主义思想确立为党的行动指南，将这一思想\n的核心内容概括为“八个明确”“十四个坚持”。\n党的十九届六中全会通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》，\n用“十个明确”对习近平新时代中国特色社会主义思想的核心内容作了进一步概括，并从十\n三个方面分领域总结成就、概括原创性理念和思想，提出“两个确立”重要论断：确立习近\n平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地\n位。\n党的十九大、十九届六中全会提出的“十个明确”、“十四个坚持”、\n“十三个方面成就”\n概括了习近平新时代中国特色社会主义思想的主要内容。\n党的二十大提出“六个必须坚持”\n，概括阐述了习近平新时代中国特色社会主义思想的\n世界观、方法论和贯穿其中的立场观点方法。","source":{"doc":"3ccc56f4000d1642c2d1","first":14,"last":14,"page":14,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-2a0c6aa1ae74cc31":[]}};
